#!/usr/bin/env node
// The coverage ledger: each health-data path, the behaviour tests that guard it, and how many negative controls
// (mutants) each test proves it catches. Guards: depth on a few paths reading as breadth (2026-08-16, the
// Simulation project reported "nothing open" with 52 of 74 claims untested). docs/coverage.md is generated by
// --write, which runs every listed node and JVM test and counts its negative controls (minutes: the JVM tests
// compile). The plain run prints the ledger and fails when a listed test changed since the ledger was written.
// Runtime: under 1 s plain. Usage: node scripts/coverage.mjs [--write]
import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import { spawnSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const LEDGER = path.join(ROOT, 'docs', 'coverage.md');

// path: [node or JVM tests that run here, browser checks that also guard it (run by browser-tier.mjs)]
const PATHS = [
  ['Web folder save', ['scripts/recorder.test.cjs'], ['recorder-page', 'monitor-log']],
  ['Web Drive save', ['scripts/recorder.test.cjs'], ['monitor-sync', 'recorder-page']],
  ['Native segment write', ['scripts/jvm/run-segment-test.cjs', 'scripts/segment-format.test.cjs'], []],
  ['Native upload', ['scripts/jvm/run-upload-test.cjs'], []],
  ['Marks', ['scripts/marks-store.test.cjs', 'scripts/csv-format.test.cjs', 'scripts/recorder.test.cjs'], ['symptom-marks', 'recorder-page']],
  ['Viewer parse', ['scripts/segment-format.test.cjs', 'scripts/day-boundary.test.cjs', 'scripts/day-gaps.test.cjs', 'scripts/row-epoch.test.cjs'], ['parse-worker', 'v2-series', 'session-time']],
  ['Native reconnect (no gap in the recording)', ['scripts/jvm/run-reconnect-test.cjs', 'scripts/engine-boundary.test.cjs'], ['strap-switch']],
  ['HR and HRV numbers (JS and native)', ['scripts/rmssd-parity.test.js', 'scripts/avg-stats.test.cjs'], ['native-rmssd']],
];

const hash = (f) => crypto.createHash('sha256').update(fs.readFileSync(path.join(ROOT, f), 'utf8').replace(/\r\n/g, '\n')).digest('hex').slice(0, 12);
const tests = [...new Set(PATHS.flatMap((p) => p[1]))];

// A test's negative controls: its own total ("all N negative controls fail") when it prints one, else the lines
// that each report one control caught, counted once per line.
function controls(out) {
  const total = [...out.matchAll(/\ball (\d+) (?:negative controls? fail|mutants caught)/gi)].map((m) => Number(m[1]));
  if (total.length) return total[total.length - 1];
  return out.split('\n').filter((l) => /FAILED as required|^caught\b|^(?:OK|PASS|ok)\b.*(?:negative control|mutant)/i.test(l)).length;
}

if (process.argv.includes('--write')) {
  const rows = {};
  for (const t of tests) {
    const t0 = Date.now();
    const r = spawnSync(process.execPath, [path.join(ROOT, t)], { cwd: ROOT, encoding: 'utf8', timeout: 900000, maxBuffer: 64 << 20 });
    const out = (r.stdout || '') + (r.stderr || '');
    rows[t] = { pass: r.status === 0, controls: controls(out), secs: Math.round((Date.now() - t0) / 1000), hash: hash(t) };
    console.log(`${rows[t].pass ? 'ok  ' : 'FAIL'} ${t}  controls=${rows[t].controls}  ${rows[t].secs} s`);
  }
  const lines = ['# Coverage ledger', '', 'Generated by `node scripts/coverage.mjs --write`; never edit by hand. `./check` prints it and fails when a',
    'listed test changed since it was written. Controls = negative controls (mutants) the test proves it catches.', '',
    '| health-data path | tests (controls) | browser checks |', '|---|---|---|'];
  for (const [name, ts, br] of PATHS) {
    lines.push(`| ${name} | ${ts.map((t) => `\`${path.basename(t)}\` (${rows[t].pass ? rows[t].controls : 'FAILING'})`).join(', ')} | ${br.map((b) => '`' + b + '`').join(', ') || 'none'} |`);
  }
  lines.push('', '<!-- hashes ' + JSON.stringify(Object.fromEntries(tests.map((t) => [t, rows[t].hash]))) + ' -->', '');
  fs.writeFileSync(LEDGER, lines.join('\n'));
  const failing = tests.filter((t) => !rows[t].pass);
  console.log(`coverage: wrote docs/coverage.md${failing.length ? '; FAILING: ' + failing.join(', ') : ''}`);
  process.exit(failing.length ? 1 : 0);
}

if (!fs.existsSync(LEDGER)) { console.log('coverage: FAIL docs/coverage.md missing; run node scripts/coverage.mjs --write'); process.exit(1); }
const text = fs.readFileSync(LEDGER, 'utf8').replace(/\r\n/g, '\n');
const stored = JSON.parse((text.match(/<!-- hashes (\{.*\}) -->/) || [])[1] || '{}');
const stale = tests.filter((t) => stored[t] !== hash(t));
for (const l of text.split('\n')) if (l.startsWith('| ') && !l.startsWith('| health') ) console.log(l);
const covered = PATHS.filter((p) => p[1].length).length;
console.log(`coverage: ${covered} of ${PATHS.length} health-data paths have node or JVM tests; ${tests.length} tests listed`);
if (stale.length) { console.log('coverage: FAIL ledger older than ' + stale.join(', ') + '; run node scripts/coverage.mjs --write'); process.exit(1); }
